(function(E){ const x = E["hr-m1"] = E["hr-m1"] || {units:{}}; x.units["hr-cp-1"] = {"writing":{"id":"c-hr-cp-1-w","title":{"en":"Your intro email to Ms Clarke","tr":"Ms Clarke'a tanışma e-postan","fa":"ایمیل معرفی تو به خانم کلارک"},"course":"hr","unit":"hr-cp-1","portfolio":null,"type":"writing","difficulty":"medium","prompt":{"en":"Write an intro email to Ms Clarke, the UK client (60-80 words): who you are, what you do, what you are working on now, and one polite request for a call time. Keep the tone friendly but formal.","tr":"İngiliz müşteri Ms Clarke'a tanışma e-postası yaz (60-80 kelime): kimsin, ne iş yapıyorsun, şu anda neyin üzerinde çalışıyorsun ve görüşme saati için kibar bir rica. Ton samimi ama resmî olsun.","fa":"یک ایمیل معرفی برای خانم کلارک، مشتری بریتانیایی، بنویس (۶۰ تا ۸۰ کلمه): تو چه کسی هستی، چه کار می‌کنی، این روزها مشغول چه کاری هستی و یک درخواست مؤدبانه برای تعیین وقت تماس. لحن ایمیل دوستانه اما رسمی باشد."},"model":"Dear Ms Clarke, I'm Leyla Karimi. I work in HR at the Atlas Logistics head office in Istanbul and I'm responsible for recruitment. At the moment I'm working on the hiring and onboarding plan for our new Dubai branch, which will support your deliveries from January. I was wondering if you could tell me a good time for a 15-minute call next week. Have you ever worked with our Dubai team? I look forward to hearing from you. Kind regards, Leyla Karimi","frame":"Dear ___, I'm ___. I work in ___ at ___ and I'm responsible for ___. At the moment I'm working on ___. I was wondering if you could ___. Kind regards, ___","words":[{"word":"responsible for"},{"word":"at the moment"},{"word":"I was wondering if"}],"minWords":60,"minSentences":5,"rubric":["Task done: who, role, current work, request for call","Organised: purpose, detail, request, close","Language: present simple vs continuous; polite request pattern","Tone: friendly and formal for a UK client"],"rubricI18n":{"tr":["Görev: kim, rol, şu anki iş, görüşme ricası","Düzen: amaç, ayrıntı, rica, kapanış","Dil: present simple ve continuous farkı; kibar rica kalıbı","Üslup: Birleşik Krallık'tan bir müşteri için samimi ve resmî"],"fa":["کامل بودن کار: چه کسی، سمت، کار فعلی، درخواست تماس","نظم: هدف، جزئیات، درخواست، پایان","زبان: تفاوت حال ساده و حال استمراری؛ الگوی درخواست مؤدبانه","لحن: دوستانه و رسمی، مناسب یک مشتری بریتانیایی"]},"parts":[{"t":{"en":"Who you are","tr":"Kim olduğun","fa":"اینکه کی هستی"},"find":["i'm","i am","my name is"],"sample":"Leyla Karimi, HR, head office in Istanbul"},{"t":{"en":"Your role","tr":"Görevin","fa":"نقشت"},"find":["responsible for","i work in","in charge of"],"sample":"responsible for recruitment"},{"t":{"en":"What you are working on now","tr":"Şu anki işin","fa":"کار فعلی‌ات"},"find":["at the moment","currently","working on"],"sample":"the hiring and onboarding plan for Dubai"},{"t":{"en":"A polite request for a call time","tr":"Görüşme saati için kibar bir rica","fa":"درخواست مؤدبانه برای زمان تماس"},"find":["i was wondering if","could you","a good time","call"],"sample":"a 15-minute call next week"}]},"speaking":{"id":"hr-cp-1-sp","course":"hr","unit":"hr-cp-1","rounds":[60,45],"topic":{"en":"Intro Call with Ms Clarke","tr":"Ms Clarke ile Tanışma Görüşmesi","fa":"تماس معرفی با خانم کلارک"},"warmup":{"en":"You have 60 seconds. Who are you and what do you do?","tr":"60 saniyen var. Sen kimsin ve ne yapıyorsun?","fa":"۶۰ ثانیه وقت داری. تو چه کسی هستی و چه کار می‌کنی؟"},"questions":[{"en":"Greet Ms Clarke and introduce your role and team.","tr":"Ms Clarke'ı karşıla ve görevini, ekibini tanıt.","fa":"به خانم کلارک سلام کن و نقش و تیمت را معرفی کن."},{"en":"The line is bad. Ask her to repeat and spell her email address.","tr":"Hat kötü. Tekrar etmesini ve e-posta adresini hecelemesini iste.","fa":"صدا خوب نمی‌رسد. از او بخواه حرفش را تکرار کند و نشانی ایمیلش را هجی کند."},{"en":"Make small talk: ask about her journey or the weather, then confirm the next call time.","tr":"Sohbet et: yolculuğunu ya da havayı sor, sonra bir sonraki görüşme saatini teyit et.","fa":"کمی گپ بزن: از سفرش یا هوا بپرس، بعد زمان تماس بعدی را قطعی کن."}],"followups":[{"en":"Repeat the whole call in 60 seconds, then 45.","tr":"Tüm görüşmeyi 60, sonra 45 saniyede tekrarla.","fa":"کل تماس را یک بار در ۶۰ ثانیه و بعد در ۴۵ ثانیه تکرار کن."}],"expressions":[{"phrase":"I'm responsible for...","meaning":{"en":"Permanent role.","tr":"Kalıcı görev.","fa":"نقش ثابت تو را می‌گوید."}},{"phrase":"Sorry, could you spell that?","meaning":{"en":"Checks a name or address.","tr":"İsim ya da adres kontrol eder.","fa":"یک نام یا نشانی را چک می‌کند."}},{"phrase":"Have you ever...?","meaning":{"en":"Small talk about experience.","tr":"Deneyim hakkında sohbet.","fa":"گپی درباره‌ی تجربه‌ها."}},{"phrase":"Sorry, could you speak up? The line is breaking up.","meaning":{"en":"Asks for help on a bad line.","tr":"Hat kötüyken yardım ister.","fa":"وقتی صدا خوب نمی‌رسد، کمک می‌خواهد."}},{"phrase":"Nice talking to you.","meaning":{"en":"A friendly way to end the call.","tr":"Görüşmeyi samimi bir şekilde bitirir.","fa":"تماس را دوستانه تمام می‌کند."}}]},"perspective":{"id":"c-hr-cp-1-p","title":{"en":"Ms Clarke opens your email","tr":"Ms Clarke e-postanı açıyor","fa":"خانم کلارک ایمیلت را باز می‌کند"},"course":"hr","unit":"hr-cp-1","type":"perspective","minSentences":2,"prompt":{"en":"You are Ms Clarke, receiving an email from someone in Istanbul you have never met. Write 2 sentences in first person: what makes you want to answer it?","tr":"İstanbul'dan, hiç tanışmadığın birinden e-posta alan Ms Clarke'sın. Birinci tekil şahısla 2 cümle yaz: bu e-postaya cevap verme isteğini ne uyandırır?","fa":"تو خانم کلارک هستی و از کسی در استانبول که هرگز ندیده‌ای ایمیلی گرفته‌ای. از زبان خودت دو جمله بنویس: چه چیزی باعث می‌شود دلت بخواهد جوابش را بدهی؟"}},"exit":{"id":"c-hr-cp-1-x","course":"hr","unit":"hr-cp-1","type":"exit","note":"All 6 items spaced: 1-2 from each unit.","items":[{"from":"hr-1-1","kind":"blank","prompt":"This week Ms Clarke ___ from her London office.","options":["works","is working","work"],"correct":1,"point":2,"why":{"en":"is working: 'this week' is temporary, so is + -ing. 'Works' is her usual routine, and 'work' doesn't agree with Ms Clarke.","tr":"is working: 'this week' geçicidir, bu yüzden is + -ing. 'Works' onun olağan düzenidir; 'work' Ms Clarke ile uyuşmaz.","fa":"is working درست است، چون this week موقتی است و is و فعل ing‌دار لازم است. works برنامه‌ی همیشگی اوست و work با Ms Clarke جور نیست."}},{"from":"hr-1-3","kind":"mcq","prompt":"Ms Clarke says: \"Sorry, the line is breaking up.\" What is the problem?","options":["The connection is bad.","She is angry with you.","The call is cancelled."],"correct":0,"point":3,"why":{"en":"'The line is breaking up' means the connection is bad and her voice cuts out. It says nothing about anger or a cancelled call.","tr":"'The line is breaking up' bağlantının kötü olduğu ve sesin kesildiği anlamına gelir. Öfke ya da iptal edilen bir görüşmeyle ilgisi yoktur.","fa":"«The line is breaking up» یعنی اتصال بد است و صدا قطع و وصل می‌شود. ربطی به عصبانیت یا لغو تماس ندارد."}},{"from":"hr-1-2","kind":"mcq","prompt":"Which sentence tells Ms Clarke that a file comes with your email?","options":["I've attached the job description.","I've confirmed the job description.","I've returned the job description."],"correct":0,"point":3,"why":{"en":"'I've attached...' says a file comes with the email. 'Confirmed' and 'returned' are other actions.","tr":"'I've attached...' e-postayla bir dosya geldiğini söyler. 'Confirmed' ve 'returned' başka eylemlerdir.","fa":"«I've attached...» می‌گوید فایلی همراه ایمیل است. confirmed و returned کارهای دیگری‌اند."}},{"from":"hr-1-3","kind":"blank","prompt":"Sorry, how ___ you spell the street name?","options":["does","do","are"],"correct":1,"point":2,"why":{"en":"do: 'you' takes do in a present simple question. 'Does' is for he, she or it, and 'are' would need -ing.","tr":"do: geniş zaman sorusunda 'you' do alır. 'Does' he, she ya da it içindir; 'are' -ing ister.","fa":"do درست است، چون در سؤال حال ساده you با do می‌آید. does برای he و she و it است و are فعل ing‌دار می‌خواهد."}},{"from":"hr-1-4","kind":"blank","prompt":"I ___ to London last year.","options":["have been","went","have gone"],"correct":1,"point":2,"why":{"en":"went: 'last year' is finished, so past simple. 'Have been' and 'have gone' can't go with a finished time.","tr":"went: 'last year' bitmiştir, bu yüzden past simple. 'Have been' ve 'have gone' bitmiş zamanla kullanılmaz.","fa":"went درست است، چون last year تمام شده و گذشته‌ی ساده می‌خواهد. have been و have gone با زمان تمام‌شده نمی‌آیند."}},{"from":"hr-1-3","kind":"mcq","prompt":"Which line checks a number on a bad line?","options":["Did you say fifteen or fifty?","You said numbers?","How many you said?"],"correct":0,"point":1,"why":{"en":"'Did you say fifteen or fifty?' gives both numbers, so the answer is clear. The other two are unclear, and 'How many you said?' has the wrong word order.","tr":"'Did you say fifteen or fifty?' iki sayıyı da söyler; böylece cevap net olur. Diğer ikisi belirsizdir; 'How many you said?' yanlış sıradadır.","fa":"«Did you say fifteen or fifty?» هر دو عدد را می‌گوید تا جواب روشن باشد. دو گزینه‌ی دیگر مبهم‌اند و «How many you said?» ترتیب کلمه‌اش غلط است."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
